///                                    * Value of the Glitch filter control register for the HPD signal. The register value specifies the time interval for which the signal level should be constant before considering that as a valid level
///                                    ###
///     @ 0x00204                      (W-)
///     #         # Stuffing bytes...
///               %% 4064
///     @ 0x00400                      (P)
///     # 0x00400 keys_sram            
///               $AKEYS               keys_sram         MEM          
///                                    ###
///                                    * HDCP KEYS SRAM
///                                    * Each key is occupies 2 locations
///                                    * write AKEY00[31:0] data in SRAM at '0' laction
///                                    * write AKEY00[55:32] data in SRAM at '1' laction
///                                    * write AKEY01[31:0] data in SRAM at '2' laction
///                                    * write AKEY01[55:32] data in SRAM at '3' laction
///                                    * ... till 40 keys.
///                                    * SW has to write 80 locations to load all AKEYS
///                                    ###
///     # # ----------------------------------------------------------
/// $ENDOFINTERFACE  # size:    1536B, bits:    3284b, padding:     0B
